  static updateTrip(fishery: 'default' | 'trawl' = 'default'): Promise<StorageResult> {
    //Pick correct doc
    const docId = this.getDocId('trip', fishery);
    
    return new Promise<StorageResult>((resolve, reject) => {
      this.reopenStorage().finally(() => {
        this.user_storage.upsert(docId, (tripDoc: any) => {
          tripDoc.trip = fishery === 'trawl' ? this.user_trawlTrip : this.user_trip;
          tripDoc.lastUpdate = new Date();
          return tripDoc;
        }).then(() => resolve({success: true}))
        .catch((err: any) => resolve({success: false, error: err}));
      });      
    });
  }

  /**
   * As with sets, any update to the current delivery calls this method to update the pending_landing document.
   * @param landing The current updated landing
   * @returns Promise resolving on completion of all database operations
   */
  static updateLanding(
    landing: GroundfishDelivery | HMSDelivery | TrawlDelivery,
    fishery: 'default' | 'trawl' = 'default',
    isDraft: boolean = false
  ): Promise<StorageResult> {

    // If there's a logbookId, we update 'logbook_edited', otherwise 'trip'
    const docId = landing.logbookId
      ? this.getDocId('logbook_edited', fishery)
      : isDraft ? (fishery === 'trawl' ? `trawl_draft_${landing.localLandingGUID}`
      : `hms_draft_${landing.localLandingGUID}`)
      : this.getDocId('trip', fishery);

    return new Promise<StorageResult>((res) => {
      this.reopenStorage().finally(() => {
        this.user_storage.upsert(docId, (landDoc: any) => {
          if (fishery === 'trawl' && landing instanceof TrawlDelivery) {
            if (landing.logbookId) landDoc.trawlDelivery = landing;
            else if (isDraft) landDoc.delivery = landing;
            else landDoc.trip.trawlDelivery = landing;       
          } else {
            // existing GF/HMS logic
            if (landing.logbookId) landDoc[landing instanceof GroundfishDelivery ? "groundFish" : "HMS"] = landing;
            else if (isDraft && landing instanceof HMSDelivery) landDoc.delivery = landing;
            else landDoc.trip[landing instanceof GroundfishDelivery ? "groundfishDelivery" : "hmsDelivery"] = landing;           
          }

          landDoc.lastUpdate = new Date();
        
          // update in-memory references
          if (fishery === 'trawl' && landing instanceof TrawlDelivery) {
            
            if (landing.logbookId) {
              LocalStorageService.edited_trawlLogbook = landing;
            } else if (isDraft) {
              let ind = LocalStorageService.trawl_drafts.findIndex(td => td.localLandingGUID == landing.localLandingGUID);
              LocalStorageService.trawl_drafts[ind] = landing;
            } else {    
              LocalStorageService.user_trawlTrip.trawlDelivery = landing;
            }

          } else {

            if (landing.logbookId) {
              if (landing instanceof GroundfishDelivery) LocalStorageService.edited_logbook.GF = landing;
              else if (landing instanceof HMSDelivery) LocalStorageService.edited_logbook.HMS = landing;
            } else if (isDraft && landing instanceof HMSDelivery) {
              const idx = LocalStorageService.hms_drafts
                .findIndex(d => d.localLandingGUID === landing.localLandingGUID);
              if (idx > -1) {
                LocalStorageService.hms_drafts[idx] = landing;
                LocalStorageService.hms_drafts$.next(LocalStorageService.hms_drafts);
              }
          
            } else {
              if (landing instanceof HMSDelivery) LocalStorageService.user_trip.hmsDelivery = landing;
              else if (landing instanceof GroundfishDelivery) LocalStorageService.user_trip.groundfishDelivery = landing;
            }
            
          }
          return landDoc;
        }).then(() => res({success: true})).catch((err) => res({success: false, error: err}));
      });
      
    });
  }


