import { ApplicationRef, Component, HostListener, OnInit } from '@angular/core';
import { SwUpdate } from '@angular/service-worker';
import { LocalStorageService } from './shared/local-storage.service';
import { LookupDataService } from './shared/lookup-data.service';
import { AuthService } from './shared/auth.service';
import { catchError, first, timeout } from 'rxjs/operators';
import { ActivatedRoute, Router, RoutesRecognized } from '@angular/router';
import { OnlineStatusService, OnlineStatusType } from 'ngx-online-status';
import { ToastrService } from 'ngx-toastr';
import { OperatorUser } from './shared/operator-user.model';
import { throwError } from 'rxjs';
import shpjs from 'shpjs';
import { ApplicationInsights } from '@microsoft/applicationinsights-web'
import { environment } from 'src/environments/environment';
import { Insights } from './shared/insights.service';

/**
 * App/Root component
 */
@Component({
  selector: 'app-root',
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent implements OnInit {
  title = 'psmfc-elog';
  displayComponent: boolean = false;

  private readonly REQUEST_TIMEOUT_MS = 3 * 1000;
  /**
   * In the app component constructor, wait for the app to stabilize then check for and apply updates. 
   * @param updates Angular service to check for new versions of the app
   * @param appRef To check app stability before applying updates
   */
  constructor(private auth: AuthService,
     private router: Router,
     private toastr: ToastrService,
      public route: ActivatedRoute,
      private onlineStatusService: OnlineStatusService,
       private lookup: LookupDataService,
        updates: SwUpdate,
         private appRef: ApplicationRef,
        private insights: Insights) {
      // Allow the app to stabilize first, before checking for an update
      const appIsStable$ = this.appRef.isStable.pipe(first(isStable => isStable === true));
      console.log('Waiting for app stabilization...');

      updates.unrecoverable.subscribe(event => {
        console.log(event.reason);
        document.location.reload();
      });

      updates.versionUpdates.subscribe(evt => {     
        switch (evt.type) {
          case 'VERSION_DETECTED':
            this.toastr.success('New app version found, please wait for reload...');
            console.log(`Downloading new app version: ${evt.version.hash}`);
            break;
          case 'VERSION_READY':
            console.log(`Current app version: ${evt.currentVersion.hash}`);
            console.log(`New app version ready for use: ${evt.latestVersion.hash}`);
            break;
          case 'VERSION_INSTALLATION_FAILED':
            console.log(`Failed to install app version '${evt.version.hash}': ${evt.error}`);
            break;
        } 
      });

      appIsStable$.subscribe({complete: () => {
        console.log('App stable, checking for update...');
        
        const updateFound = updates.checkForUpdate();
        updateFound.then((update: any) =>{
          if (update) {
            this.toastr.success('New version found, reloading...');
            document.location.reload();
          } else {
            console.log('Application up-to-date');
          }
        }).catch(_ => { console.log('%c Cannot check for updates. running in localhost or service workers are disabled or not supported', 
                                      'color: antiquewhite; font-weight: bold; background-color: black;');  });   
         }, error: (err) => { console.log("Error in waiting for stabilization"); console.log(err); }});

      router.events.subscribe(event => {
        if (event instanceof RoutesRecognized) {
          if (LocalStorageService.user_storage && 
            this.onlineStatusService.getStatus() == OnlineStatusType.ONLINE &&
            LocalStorageService.logged_in) LocalStorageService.syncUserDatabase(true);
        }
      });
    }


    @HostListener('document:visibilitychange', ['$event'])
    visibilitychange() {
      if (LocalStorageService.user_storage && 
        LocalStorageService.logged_in && 
        this.onlineStatusService.getStatus() == OnlineStatusType.ONLINE) LocalStorageService.syncUserDatabase(true);
    }


    /**
     * The 'first' thing to run whenever the app loads or is refreshed.
     * Check if a user is still logged in and perform the login sequence if they are.
     */
  ngOnInit(): void {
    console.log('Init app');
    
    //We check the login_status document in storage for a still logged in user
    LocalStorageService.openUserAccounts().then(() => {
      //If logged in, refresh access token and retrieve all data from DB
      //If refresh token has expired then logout and go to login screen
      
      if (LocalStorageService.logged_in) {
        console.log('User already logged in');
        if (this.onlineStatusService.getStatus() === OnlineStatusType.ONLINE && this.auth.checkRefreshToken().expired) {
          console.log('Refresh token expired');
          this.toastr.warning('Login session has expired. Log in again to refresh', 'Session Expired')
          LocalStorageService.logged_in = false;
          LocalStorageService.local_storage.get('login_status').then((doc: any) => {
            doc.user = '';
            doc.isLoggedIn = false;
            LocalStorageService.local_storage.put(doc);
            this.router.navigate(['login']);
            this.displayComponent = true;
          });         
        } else {
          //Refresh token is not expired, user is offline, or both
          if (this.onlineStatusService.getStatus() === OnlineStatusType.ONLINE) {
            //Refresh token has not expired            

            //Check for a migration, open storage, then sync
            LocalStorageService.checkForMigration().then((res: boolean) => {

              if (!res) {
                //Need to perform a migration
                console.log('Performing HMS migration...');
                LocalStorageService.migrateToHMSCombined().then(() => {
                //We need to get this user's couchDB connection, so try refreshing the token first
                this.auth.postRefreshToken().subscribe(result => {
                  console.log("Token refresh for couchDB account creation");
                    LocalStorageService.openLocalStorage();
                    LocalStorageService.storage_promise.then(() => {
                      LocalStorageService.syncUserDatabase();
                      this.displayComponent = true;
                      LocalStorageService.sync_promise.then(() => this.afterMigrationCheck());
                    }).catch(_ => {
                      this.displayComponent = true;
                      this.logoutUser();
                    });  
                  });                 
                }, _ => {
                  this.displayComponent = true;
                  this.logoutUser()
                });
                
              } else {

                LocalStorageService.openLocalStorage();
                LocalStorageService.storage_promise.then(() => {
                  if (LocalStorageService.current_user.couchDbConnection == "") {
                    //Need to get the user couchDB connection
                    this.auth.postRefreshToken().subscribe({
                      next: (response) => {
                      console.log("Token refresh for couchDB account creation");
                      LocalStorageService.current_user.couchDbConnection = response.couchDbConnection;                      
                      this.displayComponent = true;
                      this.afterMigrationCheck(); 
                      LocalStorageService.syncUserDatabase(true);
                      }, 
                      error: () => this.logoutUser()});
                  } else {                
                    this.displayComponent = true;
                    this.afterMigrationCheck();
                    LocalStorageService.syncUserDatabase(true);
                  }   
                });
                                                      
              }
            })          
         
          } else {
            //User is not online and might have expired refresh token      
            LocalStorageService.openLocalStorage();
            LocalStorageService.storage_promise.then(() => {
              this.displayComponent = true;
              this.lookup.retrieveLookupData();
              if (this.router.url == '/login') this.router.navigate(['menu']);
            }).catch(() => {
              console.log('Error in offline open user storage');
              this.lookup.retrieveLookupData();
              if (this.router.url == '/login') this.router.navigate(['menu']);
            })
                       
          }
        }
        
      } else {
        this.displayComponent = true;
        console.log('User is not logged in');
        this.router.navigate(['login']);
      }
    });

    fetch("../../assets/EEZ_WestCoast_PacVes_shapefile.zip")
                .then(text => text.arrayBuffer())
                .then((myshape) => shpjs(myshape))
                .then((data: any) => {
                        LocalStorageService.west_coast_eez = data.features[0].geometry;
                }).catch(e => console.log('error', e));
  }


  /**
   * Set the tokens and retrieve lookup data the go to the main menu.
   */
  afterMigrationCheck() {
    if (this.router.url == '/login') this.router.navigate(['menu']);
    if (this.auth.checkAccessToken().expired) {
      this.auth.postRefreshToken().pipe(timeout(this.REQUEST_TIMEOUT_MS), catchError((error) => {
        if (error.name === 'TimeoutError') console.error('Request timed out.');
        return throwError(error);
      }))   
      .subscribe(res => {
        LocalStorageService.current_user.refreshToken = res.refreshToken;
        LocalStorageService.current_user.accessToken = res.accessToken;
        LocalStorageService.accessToken = res.accessToken;
        LocalStorageService.updateUser(false, true);
        this.lookup.retrieveLookupData();
      }, _ => this.lookup.retrieveLookupData());
    } else {
      this.lookup.retrieveLookupData();     
    }   
    
  }


  /**
   * Update login status and go back to login.
   */
  logoutUser() {
    //If error then we have to log the user out                  
    LocalStorageService.logged_in = false;
    LocalStorageService.local_storage.get('login_status').then((doc: any) => {
      doc.user = '';
      doc.isLoggedIn = false;
      LocalStorageService.local_storage.put(doc);                    
    });
    LocalStorageService.current_user = new OperatorUser();
    this.router.navigate(['login'])
  }
}
